style.css:
@-moz-document domain("roblox.com") {
/* ---------- 1. COLOR VARIABLES (edit these) ---------- */
  :root {
    --rt-bg:          #000000;  /* page background */
    --rt-surface:     #000000;  /* cards, panels */
    --rt-surface-2:   #480000;  /* hover, inputs, headers */
    --rt-border:      #480000;
    --rt-text:        #e03c3c;  /* bright red */
    --rt-text-muted:  #a82a2a;  /* dimmer red */
    --rt-accent:      #480000;  /* buttons */
    --rt-accent-hover:#6a0000;  /* button hover */
    --rt-link:        #8b0000;  /* links */
    --rt-link-hover:  #8b0000;  /* link hover */
    --rt-radius:      10px;
  }

  /* ---------- 1b. ROBLOX DESIGN TOKENS ----------
     Roblox colors most of its UI (sidebar, cards, text) through these
     variables, so overriding them themes the white/grey areas too. */
  html, body, .light-theme, .dark-theme, .rbx-body {
    --color-surface-0:   #000000 !important;
    --color-surface-100: #000000 !important;
    --color-surface-200: #000000 !important;
    --color-surface-300: #480000 !important;
    --color-surface-400: #480000 !important;
    --color-content-default:  var(--rt-text) !important;
    --color-content-emphasis: var(--rt-text) !important;
    --color-content-muted:    var(--rt-text-muted) !important;
    --color-divider-default:  var(--rt-border) !important;
    --color-stroke-default:   var(--rt-border) !important;
    --color-action-standard-background: #480000 !important;
  }

  /* ---------- 1c. LEFT SIDEBAR ---------- */
  #navigation, #left-navigation-container,
  .rbx-left-col, [class*="left-col"], [class*="left-nav"],
  [id*="left-navigation"], .left-col-list {
    background-color: #000000 !important;
    border-right: 1px solid var(--rt-border) !important;
  }

  .left-col-list li, .left-col-list a, .menu-option,
  .left-col-list [class*="premium"], .left-col-list [class*="card"] {
    background-color: transparent !important;
    color: var(--rt-text) !important;
  }

  /* active page + hover */
  .left-col-list li.active, .left-col-list li:hover,
  .left-col-list a.active, .left-col-list a:hover,
  .menu-option.active, .menu-option:hover {
    background-color: #480000 !important;
    border-radius: var(--rt-radius) !important;
  }

  /* "Roblox Plus" promo box at the bottom of the sidebar */
  .left-col-list ~ div, #left-navigation-container > div:last-child {
    background-color: #000000 !important;
    border: 1px solid var(--rt-border) !important;
    border-radius: var(--rt-radius) !important;
    color: var(--rt-text-muted) !important;
  }

  /* dark sidebar icons -> red (approximate tint) */
  .left-col-list [class*="icon-"], .left-col-list svg {
    filter: invert(20%) sepia(90%) saturate(5000%) hue-rotate(345deg) brightness(95%) !important;
  }

  /* ---------- 2. PAGE BACKGROUND & TEXT ---------- */
  html, body,
  body.light-theme, body.dark-theme,
  .container-main, .content, #wrap, .rbx-body,
  #rbx-body, .rbx-left-col, .rbx-right-col {
    background-color: var(--rt-bg) !important;
    color: var(--rt-text) !important;
  }

  h1, h2, h3, h4, h5, h6,
  .font-header-1, .font-header-2,
  .text-label, .text-lead, .text-name,
  .game-card-name, label, th, td, p, span, li {
    color: var(--rt-text);
  }

  .text-secondary, .text-footer, .xsmall, .small,
  .text-description, .game-card-info, .rbx-lead {
    color: var(--rt-text-muted) !important;
  }

  /* ---------- 3. TOP & SIDE NAVIGATION ---------- */
  .rbx-header, .navbar-fixed-top, .navbar-white,
  #header, #navigation, .rbx-navbar,
  .left-col-list, #left-navigation-container,
  .rbx-left-col .left-col-list {
    background-color: var(--rt-surface) !important;
    border-color: var(--rt-border) !important;
  }

  .rbx-navbar a, .rbx-header a,
  .left-col-list a, .menu-option-content {
    color: var(--rt-text) !important;
  }

  .rbx-navbar a:hover, .left-col-list li:hover,
  .left-col-list li.active, .menu-option:hover {
    background-color: var(--rt-surface-2) !important;
    color: var(--rt-link) !important;
  }

  .rbx-navbar-search input,
  #navbar-universal-search input {
    background-color: var(--rt-surface-2) !important;
    color: var(--rt-text) !important;
    border: 1px solid var(--rt-border) !important;
    border-radius: var(--rt-radius) !important;
  }

  /* ---------- 4. CARDS, SECTIONS, GAME TILES ---------- */
  .section, .section-content, .container-header + div,
  .game-card-container, .game-card, .list-item,
  .card, .panel, .rbx-tabs-horizontal,
  .profile-container, .profile-about,
  .item-card-container, .catalog-item-container,
  .rbx-popover-content, .popover-content {
    background-color: var(--rt-surface) !important;
    border: 1px solid var(--rt-border) !important;
    border-radius: var(--rt-radius) !important;
    box-shadow: none !important;
  }

  .game-card-container:hover,
  .item-card-container:hover,
  .catalog-item-container:hover {
    border-color: var(--rt-accent) !important;
    transform: translateY(-2px);
    transition: transform .15s ease, border-color .15s ease;
  }

  .game-card-thumb, .item-card-thumb-container,
  .thumbnail-2d-container {
    border-radius: calc(var(--rt-radius) - 2px) !important;
  }

  /* ---------- 5. BUTTONS ---------- */
  .btn-primary-md, .btn-primary-lg, .btn-primary-sm,
  .btn-growth-md, .btn-growth-lg, .btn-cta-md,
  .btn-common-play-game-lg, .btn-primary {
    background-color: var(--rt-accent) !important;
    border-color: var(--rt-accent) !important;
    color: #fff !important;
    border-radius: var(--rt-radius) !important;
  }

  .btn-primary-md:hover, .btn-primary-lg:hover,
  .btn-growth-md:hover, .btn-cta-md:hover,
  .btn-common-play-game-lg:hover {
    background-color: var(--rt-accent-hover) !important;
    border-color: var(--rt-accent-hover) !important;
  }

  .btn-secondary-md, .btn-secondary-lg, .btn-secondary-sm,
  .btn-control-md, .btn-control-sm, .btn-control-xs,
  .btn-generic-more-sm {
    background-color: var(--rt-surface-2) !important;
    border: 1px solid var(--rt-border) !important;
    color: var(--rt-text) !important;
    border-radius: var(--rt-radius) !important;
  }

  .btn-secondary-md:hover, .btn-control-md:hover {
    border-color: var(--rt-accent) !important;
  }

  /* ---------- 5b. PLAY BUTTON ---------- */
  .btn-common-play-game-lg,
  .btn-common-play-game-lg.btn-primary-md,
  .btn-common-play-game-lg.btn-primary-lg,
  [data-testid="play-button"],
  #game-details-play-button-container button,
  .game-details-play-button-container button,
  .btn-growth-lg, .btn-cta-lg {
    background-color: #000000 !important;
    border: 2px solid #480000 !important;
    color: var(--rt-text) !important;
    border-radius: var(--rt-radius) !important;
  }

  .btn-common-play-game-lg:hover,
  [data-testid="play-button"]:hover,
  #game-details-play-button-container button:hover,
  .game-details-play-button-container button:hover,
  .btn-growth-lg:hover, .btn-cta-lg:hover {
    background-color: #480000 !important;
    border-color: #6a0000 !important;
  }

  /* play triangle icon */
  .btn-common-play-game-lg [class*="icon-"],
  .btn-common-play-game-lg span[class*="icon"] {
    filter: invert(20%) sepia(90%) saturate(5000%) hue-rotate(345deg) brightness(95%) !important;
  }

  /* ---------- 6. LINKS ---------- */
  a, .text-link {
    color: var(--rt-link);
  }
  a:hover, .text-link:hover {
    color: var(--rt-link-hover);
  }

  /* ---------- 7. INPUTS, TABS, DROPDOWNS, MODALS ---------- */
  input, textarea, select,
  .form-control, .input-field {
    background-color: var(--rt-surface-2) !important;
    color: var(--rt-text) !important;
    border: 1px solid var(--rt-border) !important;
    border-radius: 8px !important;
  }
  input:focus, textarea:focus, select:focus {
    border-color: var(--rt-accent) !important;
    outline: none !important;
  }

  .rbx-tab, .rbx-tab-heading, .tab-button {
    background-color: transparent !important;
    color: var(--rt-text-muted) !important;
  }
  .rbx-tab.active, .rbx-tab:hover,
  .rbx-tab.active .rbx-tab-heading {
    color: var(--rt-link) !important;
    border-bottom-color: var(--rt-link) !important;
  }

  .dropdown-menu, .modal-content, .modal-dialog .modal-content,
  .popover, .simplemodal-container {
    background-color: var(--rt-surface) !important;
    border: 1px solid var(--rt-border) !important;
    color: var(--rt-text) !important;
    border-radius: var(--rt-radius) !important;
  }
  .dropdown-menu li a:hover {
    background-color: var(--rt-surface-2) !important;
  }

  /* ---------- 8. FOOTER & SCROLLBAR ---------- */
  footer, .footer, #footer, .container-footer {
    background-color: var(--rt-surface) !important;
    border-top: 1px solid var(--rt-border) !important;
  }

  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: var(--rt-bg); }
  ::-webkit-scrollbar-thumb {
    background: var(--rt-border);
    border-radius: 6px;
  }
  ::-webkit-scrollbar-thumb:hover { background: var(--rt-accent); }

  ::selection { background: var(--rt-accent); color: #fff; }

  /* ---------- 9. CUSTOM BACKGROUND IMAGE ----------
     Kept at the end so it overrides the solid colors above. */
  html {
    background: linear-gradient(rgba(0,0,0,.65), rgba(0,0,0,.65)),
                url("https://i.pinimg.com/1200x/65/6d/79/656d79d6b3c218ab578e79e4fb1be0a8.jpg") center / cover fixed no-repeat !important;
  }
  body, .container-main, .content, #wrap, .rbx-body, #rbx-body,
  .rbx-left-col, .rbx-right-col {
    background-color: transparent !important;
  }

  /* semi-transparent panels so the image shows through */
  .section, .game-card-container, .item-card-container,
  .catalog-item-container, .profile-container, .card, .panel {
    background-color: rgba(0,0,0,.78) !important;
  }
  #navigation, #left-navigation-container, .left-col-list,
  .rbx-header, .navbar-fixed-top {
    background-color: rgba(0,0,0,.85) !important;
  }
}
